CREATE TABLE [dbo].[TREC_ESPECIALIDADES](	  [esp_id] INT NOT NULL IDENTITY(1,1)	, [cli_id] INT NOT NULL	, [esp_nombre] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [esp_activo] SMALLINT NOT NULL DEFAULT((1))	, [esp_descripcion] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, CONSTRAINT [PK_TREC_ESPECIALIDADES] PRIMARY KEY ([esp_id] ASC))